/** Attributes are key-value pairs where the key is a static string (e.g. a string literal),
 *  and the value is a variant. In the case of the carb::cpp::string_view variant, the
 *  \ref Attribute object does not allocate memory and does not own the string. This is because
 *  it is designed for use with instrument functions to specify a set of attributes. In this
 *  context users pass an optional list of attributes, for example:
 *
 *  @code{.cpp}
 *  add(counter, 10, {{"service", "database"}, {"status", 200}});
 *  @endcode
 *
 *  An alternative syntax is supported, which is based on simple structs that define a data
 *  member value. for example:
 *
 *  @code{.cpp}
 *  struct service { carb::cpp::string_view value; };
 *  struct status { int value; };
 *  @endcode
 *
 *  and then:
 *
 *  @code{.cpp}
 *  add(counter, 10, service{"database"}, status{200});
 *  @endcode
 *
 *  which is equivalent to:
 *
 *  @code{.cpp}
 *  add(counter, 10, {{"service", "database"}, {"status", 200}});
 *  @endcode
 *
 *  It is not a good idea to define any members other than the value member.
 *
 *  The struct-based approach effectively reflects the attribute name in the C++ type system,
 *  which has the benefit of preventing bugs caused by mispelling of the attribute name, as
 *  well as allowing trait-based association of additional data, if needed.
 *
 *  When attributes are used with an instrument, e.g. a counter, the set of attributes, together
 *  with the instrument name, identify an individual metric. For example, in the case of a counter
 *  instrument, each unique set of attributes identifies a different count (which in addition can be
 *  aggregated in several different ways).
 *
 *  CARDINALITY WARNING: Take care to not use attributes that can hold arbitrary values, for
 *  example a user name. Failure to pay attention to this can lead to the so-called high
 *  cardinality problem, where the number of unique metrics becomes too large to be manageable.
 */
using Attribute = omni::otel::Attribute;

/** Type alias for omni.otel instrument observer. */
template <class T>
using InstrumentObserver = omni::otel::InstrumentObserver<T>;

/** Type alias for omni.otel observable instrument callback. */
template <class T>
using ObservableInstrumentCallback = omni::otel::ObservableInstrumentCallback<T>;

