    /** Get a counter instrument for std::uint64_t values by hash.
     *  @param[in] hash Hash value used to identify the instrument.
     *  @param[in] name The name of the counter instrument.
     *  @param[in] description A description of what the counter measures.
     *  @param[in] unit The unit of measurement (e.g., "bytes", "requests").
     *  @returns A pointer to the counter, or nullptr on failure. The caller must not take ownership
     *           of the returned pointer. The pointer is not safe to store for later use.
     *  @remarks For a given hash value, name, description, and unit must be identical across
     *           all calls. For example, it is invalid to call this function with the same hash
     *           but different name, description, or unit values.
     */
    virtual ICounter<std::uint64_t>* getCounterByHash_uint64_t(std::uint32_t hash,
                                                               carb::cpp::string_view name,
                                                               carb::cpp::string_view description,
                                                               carb::cpp::string_view unit) noexcept = 0;

