// Factory functions for creating instruments

/** Create a counter instrument with the specified value type T.
 *
 *  @param[in] meter The meter to create the counter with.
 *  @param[in] name The name of the counter instrument.
 *  @param[in] description A description of what the counter measures.
 *  @param[in] unit The unit of measurement (e.g., "bytes", "requests").
 *
 *  @returns An \ref carb::ObjectPtr to the created counter, or nullptr on failure.
 *
 *  @remarks This is a convenience namespace-scope function template that is
 *           implemented in terms of the corresponding IMeter member function template.
 *           The @p meter argument is permitted to be null, in which case a null
 *           instrument pointer is returned.
 *
 *  @remarks Namespace-scope instrument manipulators (e.g. add) defined further
 *           down can be called with a null instrument pointer.
 */
template <class T>
carb::ObjectPtr<ICounter<T>> createCounter(const carb::ObjectPtr<IMeter>& meter,
                                           carb::cpp::string_view name,
                                           carb::cpp::string_view description,
                                           carb::cpp::string_view unit = "")
{
    if (!meter)
        return {};
    return carb::stealObject(meter->createCounter<T>(name, description, unit));
}


