/** Add a value to a counter with variadic attributes.
 *
 *  @param[in] counter The counter instrument to add to (null pointer is permitted).
 *  @param[in] value The value to add to the counter.
 *  @param[in] a Variadic list of attributes to associate with this measurement.
 *
 *  @remarks If the @p counter \ref carb::ObjectPtr is null, this function is a no-op.
 */
template <class T, class U, class... A>
void add(const carb::ObjectPtr<ICounter<T>>& counter, U value, A&&... a) noexcept
{
    if (counter)
        counter->add(value, std::forward<A>(a)...);
}

